-- 104: the rest of Wiener Prater from Carter's RCDB screenshots, 2026-10-31.
-- New: Race (SBF Visa F1 Vortex MX607, 2014), Roller Ball (RES Rides, 13 Jun
-- 2020), Wiener Looping (MACK BigDipper, 101.7 ft, 50.3 mph, 1,699.5 ft, 3 inv,
-- 23 May 2025). Filled: Volare, Wilde Maus (Maurer Wild Maus Classic), Zug des
-- Manitu (CAM Baby Kart powered mine train, 2002; RCDB has 0 inversions only).
-- Safe to run twice.
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Race', 'Wiener Prater', 'Steel', 'SBF Visa', NULL, NULL, NULL, NULL, 0, NULL, 2014, '2014', 'year', NULL, NULL, 1 WHERE NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Race' AND park = 'Wiener Prater');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Race' AND c.park = 'Wiener Prater' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND json_extract(a.detail, '$.id') = c.id);
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Roller Ball', 'Wiener Prater', 'Steel', 'RES Rides', NULL, NULL, NULL, NULL, 0, NULL, 2020, '2020-06-13', 'day', NULL, NULL, 1 WHERE NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Roller Ball' AND park = 'Wiener Prater');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Roller Ball' AND c.park = 'Wiener Prater' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND json_extract(a.detail, '$.id') = c.id);
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Wiener Looping', 'Wiener Prater', 'Steel', 'MACK Rides', 'MACK BigDipper', 101.7, 50.3, 1699.5, 3, 72, 2025, '2025-05-23', 'day', NULL, NULL, 1 WHERE NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Wiener Looping' AND park = 'Wiener Prater');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Wiener Looping' AND c.park = 'Wiener Prater' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND json_extract(a.detail, '$.id') = c.id);
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_edited', name, 8, json_object('id', id, 'fields', json_array('h', 's', 'l', 'inv', 'dur', 'yr', 'opened', 'openedPrec'), 'via', '104') FROM coasters WHERE name = 'Volare' AND park = 'Wiener Prater' AND l IS NULL;
UPDATE coasters SET h = 68.9, s = 31.1, l = 1437.0, inv = 2, dur = 80, yr = 2004, opened = '2004-04-03', openedPrec = 'day' WHERE name = 'Volare' AND park = 'Wiener Prater' AND l IS NULL;
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_edited', name, 10, json_object('id', id, 'fields', json_array('manu', 'model', 'h', 's', 'l', 'inv', 'dur', 'yr', 'opened', 'openedPrec'), 'via', '104') FROM coasters WHERE name = 'Wilde Maus' AND park = 'Wiener Prater' AND l IS NULL;
UPDATE coasters SET manu = 'Maurer Rides', model = 'Maurer Wild Mouse', h = 49.3, s = 28.0, l = 1213.9, inv = 0, dur = 70, yr = 1997, opened = '1997', openedPrec = 'year' WHERE name = 'Wilde Maus' AND park = 'Wiener Prater' AND l IS NULL;
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_edited', name, 5, json_object('id', id, 'fields', json_array('manu', 'inv', 'yr', 'opened', 'openedPrec'), 'via', '104') FROM coasters WHERE name = 'Zug des Manitu' AND park = 'Wiener Prater' AND manu IS NULL;
